function Icon({ name, size = 20, fill = false }: { name: string; size?: number; fill?: boolean }) {
  const common = { width: size, height: size, viewBox: '0 0 24 24', fill: fill ? 'currentColor' : 'none', stroke: 'currentColor', strokeWidth: 1.5, strokeLinecap: 'round' as const, strokeLinejoin: 'round' as const, 'aria-hidden': true as const };
  const paths: Record<string, ReactNode> = {
    search: <><circle cx="10.8" cy="10.8" r="7.3"/><path d="m16.3 16.3 5 5"/></>, user: <><circle cx="12" cy="7.5" r="3.5"/><path d="M4.5 21c.4-4.1 3.1-6.5 7.5-6.5s7.1 2.4 7.5 6.5"/></>,
    heart: <path d="M20.8 8.5c0 4.7-8.8 11-8.8 11S3.2 13.2 3.2 8.5a4.5 4.5 0 0 1 8.8-1.2 4.5 4.5 0 0 1 8.8 1.2Z"/>,
    bag: <><path d="M4.5 8h15l-1 13h-13l-1-13Z"/><path d="M9 9V6a3 3 0 0 1 6 0v3"/></>, menu: <><path d="M3 7h18M3 12h18M3 17h18"/></>, close: <path d="M5 5 19 19M19 5 5 19"/>,
    arrow: <><path d="M3 12h17m-7-7 7 7-7 7"/></>, left: <><path d="M20 12H4m7-7-7 7 7 7"/></>, chevron: <path d="m9 5 7 7-7 7"/>, down: <path d="m6 9 6 6 6-6"/>,
    plus: <path d="M12 5v14M5 12h14"/>, minus: <path d="M5 12h14"/>, check: <path d="m4 12 5 5L20 6"/>, trash: <><path d="M4 7h16M9 7V4h6v3m3 0-1 13H7L6 7"/><path d="M10 11v5m4-5v5"/></>,
    sparkle: <><path d="M12 2 14 10l8 2-8 2-2 8-2-8-8-2 8-2 2-8Z"/></>, shield: <><path d="M12 2 20 5v6c0 5-3 8-8 11-5-3-8-6-8-11V5l8-3Z"/><path d="m9 12 2 2 4-4"/></>, chat: <path d="M20 11a8 8 0 0 1-8 8 8.5 8.5 0 0 1-3-.5L4 20l1.5-4A8 8 0 1 1 20 11Z"/>,
  };
  return <svg {...common}>{paths[name]}</svg>;
}
